// ========================================
// META WEBHOOK HANDLER - PRODUCTION
// ========================================

try {
  const VERIFY_TOKEN = "123456";
  const query = $json.query || {};
  const mode = query["hub.mode"];
  const token = query["hub.verify_token"];
  const challenge = query["hub.challenge"];

  // Handle verification
  if (mode) {
    if (mode === "subscribe" && token === VERIFY_TOKEN) {
      return { challenge, skipProcessing: true };
    }
    return { error: "Forbidden", skipProcessing: true };
  }

  // Handle incoming message
  const body = $input.item?.json?.body || $input.item?.json;

  if (!body?.entry?.[0]?.changes?.[0]?.value) {
    return { skipProcessing: true };
  }

  const value = body.entry[0].changes[0].value;

  // ?? STRICT GUARD: skip everything that isn't an inbound customer message ??
  if (!value.messages || value.messages.length === 0) {
    return { skipProcessing: true };
  }

  // Skip if this is a status update batch (even if messages array exists)
  if (value.statuses && value.statuses.length > 0) {
    return { skipProcessing: true };
  }

  const message = value.messages[0];
  const contact = value.contacts?.[0];

  // Only process text and interactive messages
  if (message.type !== 'text' && message.type !== 'interactive') {
    return { skipProcessing: true };
  }

  // Skip messages older than 60 seconds (WA retry queue replays old messages)
  const msgAge = Math.floor(Date.now() / 1000) - parseInt(message.timestamp || 0);
  if (msgAge > 300) {
    console.log('Skipping stale message, age:', msgAge, 's, from:', message.from);
    return { skipProcessing: true };
  }

  // Skip empty messages
  const messageText = message.text?.body || message.interactive?.button_reply?.title || '';
  if (!messageText.trim()) {
    return { skipProcessing: true };
  }

  return {
    skipProcessing: false,
    messageId: message.id,
    phoneNumber: message.from,
    customerName: contact?.profile?.name || "Customer",
    messageText: messageText,
    messageType: message.type,
    timestamp: message.timestamp
  };
} catch (error) {
  console.error('Webhook parse error:', error);
  return { 
    skipProcessing: true, 
    error: error.message 
  };
}

// ========================================
// BUILD AI CONTEXT - WITH SEPARATE ORDER DATA
// ========================================

const prepareData = $('Prepare Data').item.json;
const conversation = $('Get Conversation').item.json;
const customer = $('Get Customer Data').item.json;

console.log('=== BUILD AI CONTEXT ===');

// Safe parsing with fallbacks
let customerData = {};
try {
  const rawCustomer = customer.data || customer.propertyName || customer;
  customerData = typeof rawCustomer === 'string' ? JSON.parse(rawCustomer) : rawCustomer;
  if (!customerData || typeof customerData !== 'object') {
    customerData = {};
  }
} catch (e) {
  console.error('Customer parse error:', e.message);
  customerData = {};
}

let conversationHistory = [];
try {
  const rawConversation = conversation.data || conversation.propertyName || conversation;
  conversationHistory = typeof rawConversation === 'string' ? JSON.parse(rawConversation) : rawConversation;

  if (!Array.isArray(conversationHistory)) {
    conversationHistory = [];
  }

  conversationHistory = conversationHistory.filter(msg => 
    msg && typeof msg === 'object' && msg.role && msg.content && typeof msg.content === 'string'
  );
} catch (e) {
  console.error('Conversation parse error:', e.message);
  conversationHistory = [];
}

// Build conversation context
let context = 'No previous messages.';
if (conversationHistory.length > 0) {
  context = conversationHistory.slice(-8).map(msg => {
    const role = msg.role === 'user' ? 'Customer' : 'You';
    return `${role}: ${msg.content}`;
  }).join('\n');
}

// ========================================
// KEY FIX: Separate PERMANENT profile from TEMPORARY order data
// ========================================

// Detect language if not set
let language = customerData.language;
if (!language) {
  const msgLower = (prepareData.message || '').toLowerCase();
  const enWords = ['hello','hi','hey','thanks','please','order','confirm','cancel','yes','no','morning','afternoon','evening'];
  const idWords = ['halo','hai','selamat','terima kasih','tolong','pesan','konfirmasi','batal','ya','tidak','mau','saya','oke','dong'];
  const enScore = enWords.filter(w => msgLower.includes(w)).length;
  const idScore = idWords.filter(w => msgLower.includes(w)).length;
  language = idScore >= enScore ? 'id' : 'en';
}

// PERMANENT customer data (NEVER includes order-specific fields)
const profile = {
  name: customerData.name || prepareData.name || 'Unknown',
  phone: prepareData.phone,
  preferences: customerData.preferences || null,  // Only permanent preferences
  language: language
};

// Check if there's an active order in the last 5 messages
let hasActiveOrder = false;
for (let i = conversationHistory.length - 1; i >= Math.max(0, conversationHistory.length - 5); i--) {
  const msg = conversationHistory[i];
  if (msg.role === 'assistant' && msg.content && 
      (msg.content.includes('ORDER SUMMARY') || 
       msg.content.includes('ORDER CONFIRMED') ||
       msg.content.includes('Please provide your order details'))) {
    hasActiveOrder = true;
    break;
  }
}

// TEMPORARY order data - ONLY used if there's an active order
let orderData = {
  eventDate: null,
  eventType: null,
  menu: null,
  menuItems: null,
  quantity: null,
  address: null,
  specialRequests: null
};

// Only load order data from customer profile if there's an active order
if (hasActiveOrder) {
  orderData = {
    eventDate: customerData.eventDate || null,
    eventType: customerData.eventType || null,
    menu: customerData.menu || null,
    menuItems: customerData.menuItems || null,
    quantity: customerData.quantity || null,
    address: customerData.address || null,
    specialRequests: customerData.specialRequests || null
  };
}

console.log('Profile (permanent):', JSON.stringify(profile));
console.log('Order Data (temporary):', JSON.stringify(orderData));
console.log('Has Active Order:', hasActiveOrder);

// Prevent double-processing of rapid-fire webhooks
const lastMsg = conversationHistory[conversationHistory.length - 1];
const justReplied = lastMsg && 
  lastMsg.role === 'assistant' && 
  lastMsg.timestamp &&
  (Date.now() - new Date(lastMsg.timestamp).getTime()) < 3000;

if (justReplied && !prepareData.message) {
  console.log('?? Skipping - just replied within 3 seconds');
  return { skipProcessing: true };
}

// ========================================
// LANGUAGE DETECTION (per-message)
// ========================================
const englishIndicators = [
  'i would', 'i want', 'i need', 'please', 'hello', 'hi', 'hey',
  'good morning', 'good afternoon', 'good evening', 'thank you',
  'confirm', 'help me', 'can you', 'could you', 'would like',
  "i'm", 'order please', 'yes please'
];
const indonesianIndicators = [
  'halo', 'hai', 'selamat', 'terima kasih', 'mau pesan', 'saya mau',
  'saya ingin', 'makasih', 'sudah', 'belum', 'minta', 'okee', 'iya'
];
const msgLowerLang = (prepareData.message || '').toLowerCase().trim();
const enScore = englishIndicators.filter(w => msgLowerLang.includes(w)).length;
const idScore = indonesianIndicators.filter(w => msgLowerLang.includes(w)).length;

let detectedLang;
if (enScore > 0 && enScore >= idScore) {
  detectedLang = 'en';
} else if (idScore > 0) {
  detectedLang = 'id';
} else {
  // Fall back to recent user message history
  const recentUserMsgs = conversationHistory.filter(h => h.role === 'user').slice(-5);
  let histEn = 0, histId = 0;
  for (const h of recentUserMsgs) {
    const c = (h.content || '').toLowerCase();
    histEn += englishIndicators.filter(w => c.includes(w)).length;
    histId += indonesianIndicators.filter(w => c.includes(w)).length;
  }
  if (histEn > histId) detectedLang = 'en';
  else if (histId > histEn) detectedLang = 'id';
  else detectedLang = profile.language || 'id';
}
console.log('Lang detected:', detectedLang, '| enScore:', enScore, '| idScore:', idScore);

return {
  phone: prepareData.phone,
  name: profile.name,
  message: prepareData.message || '',
  messageId: prepareData.messageId,
  conversationHistory,
  conversationContext: context,
  customerProfile: profile,      // ? Permanent only
  orderData: orderData,           // ? Temporary order data
  hasActiveOrder: hasActiveOrder,
  lang: detectedLang
};

// ========================================
// SMART ROUTER - WITH POST-HOLIDAY DATE HANDLING
// ========================================

const context = $input.item.json;
const msg = (context.message || '').toLowerCase().trim();
const history = context.conversationHistory || [];

// Find last assistant message (used multiple times)
const lastAssistantMsg = [...history].reverse().find(h => h.role === 'assistant');

// YES after "would you like to order?" → fresh order form
const lastAsstMsg = [...history].reverse().find(h => h.role === 'assistant');
const lastAsstContent = (lastAsstMsg && lastAsstMsg.content) || '';
const isOpenConfirmMsg = lastAsstContent.includes('place an order') || lastAsstContent.includes('mau memesan') || lastAsstContent.includes('ingin memesan');
const isYesReply = ['yes','ya','yeah','yep','iya','sure','ok','oke'].some(w => msg === w || msg.startsWith(w + ' '));
if (isOpenConfirmMsg && isYesReply) {
  console.log('Yes after open-confirm → fresh order form');
  return { flow: 'order', context: { ...context, _freshOrder: true } };
}

// ACKNOWLEDGMENT - Short responses after rejection or info
const ackKeywords = ['okay', 'ok', 'oke', 'alright', 'i see', 'got it', 'noted', 'understood', 'sure'];
const lastMsgIsOrderSummary = lastAssistantMsg && (
  lastAssistantMsg.content.includes('ORDER SUMMARY') ||
  lastAssistantMsg.content.includes('RINGKASAN PESANAN')
);
if (!lastMsgIsOrderSummary && ackKeywords.some(k => msg === k || msg.startsWith(k + ' ') || msg.endsWith(' ' + k))) {
  if (lastAssistantMsg && lastAssistantMsg.content.includes("we're closed on")) {
    return { flow: 'chat', context: { ...context, _isAfterHolidayRejection: true } };
  }
  return { flow: 'chat', context: context };
}

// CANCEL INTENT - Check first!
const cancelKeywords = ['cancel', 'batal', 'nevermind', 'no thanks', 'not now', 'stop'];
if (cancelKeywords.some(k => msg.includes(k))) {
  return { flow: 'chat', context: context };
}

// ???????????????????????????????????????????????????
// FRESH ORDER: standalone order words ? blank form
// ???????????????????????????????????????????????????
const freshOrderWords = [
  'order', 'pesan', 'catering', 
  'new order', 'start order', 'place order',
  'mau order', 'mau pesan', 'ingin order', 'ingin pesan',
  'boleh order', 'boleh pesan'
];
if (freshOrderWords.some(w => msg === w)) {
  console.log('?? Fresh order ? blank form');
  return { flow: 'order', context: { ...context, _freshOrder: true } };
}

// ?? ORDER MODE DETECTION (check BEFORE greetings)
// Check if last assistant was asking for a different date
const isCheckingAvailability = lastAssistantMsg && (
  lastAssistantMsg.content.includes('choose another date') ||
  lastAssistantMsg.content.includes('which date works')
);

const lastMsg = history[history.length - 1];
const isInOrderMode = lastMsg && lastMsg.role === 'assistant' && (
  lastMsg.content.includes('Please provide') || 
  lastMsg.content.includes('Still need') ||
  lastMsg.content.includes('ORDER SUMMARY') ||
  lastMsg.content.includes('RINGKASAN PESANAN') ||
  lastMsg.content.includes('Masih kurang') ||
  lastMsg.content.includes('Berikut data') ||
  lastMsg.content.includes('Silakan isi') ||
  lastMsg.content.includes("Got it") ||
  lastMsg.content.includes("Siap") ||
  lastMsg.content.includes("Here's what I have") ||
  lastMsg.content.includes('Ini yang saya catat') ||
  lastMsg.content.includes('Which menu') ||
  lastMsg.content.includes('Menu apa') ||
  lastMsg.content.includes("What's the occasion") ||
  lastMsg.content.includes('Untuk acara apa') ||
  lastMsg.content.includes('How many people') ||
  lastMsg.content.includes('Untuk berapa orang')
);

// ?? FIX: Don't route to order if just a casual greeting
const isGreeting = ['hi', 'hello', 'hey', 'halo', 'hai', 'pagi', 'siang', 'malam', 'test'].some(g => 
  msg === g || msg.startsWith(g + ' ') || msg.startsWith(g + ',')
);

if ((isInOrderMode || isCheckingAvailability) && !isGreeting) {
  return { flow: 'order', context: context };
}

// ?? POST-HOLIDAY DATE QUERIES: Customer asks about specific date after rejection
// Check if ANY assistant message in history contains holiday rejection
const wasHolidayRejected = history.some(h => 
  h.role === 'assistant' && (h.content.includes("we're closed on") || h.content.includes("can't accept orders"))
);

const isAfterHoliday = wasHolidayRejected && lastAssistantMsg && 
  (lastAssistantMsg.content.includes("we're closed on") ||
   lastAssistantMsg.content.includes("can't accept orders") ||
   lastAssistantMsg.content.includes("Sure") ||
   lastAssistantMsg.content.includes("No problem") ||
   lastAssistantMsg.content.includes("choose another date") ||
   lastAssistantMsg.content.includes("which date"));

// NEW: Detect "what about" queries for new dates after holiday
const whatAboutPattern = /what about|how about|try|check|available on|for\s+(\d{1,2}(?:st|nd|rd|th)?\s*(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec))/i;

if (wasHolidayRejected && whatAboutPattern.test(msg)) {
  console.log('?? New date query after holiday detected in Smart Router');
  return { flow: 'order', context: { ...context, _isNewDateAfterHoliday: true } };
}

if (isAfterHoliday) {
  const hasDatePattern = /\d{1,2}(?:st|nd|rd|th)?/i.test(msg) || 
                         /(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)/i.test(msg);
  const dateQuestionWords = ['what about', 'how about', 'available', 'can', 'could', 'would', 'is', 'are', 'for'];
  const isDateQuestion = dateQuestionWords.some(w => msg.includes(w));

  if (hasDatePattern && isDateQuestion) {
    return { flow: 'order', context: { ...context, _checkingNewDate: true } };
  }

  // Even without date pattern, if asking about availability, route to order
  if (isDateQuestion) {
    return { flow: 'order', context: context };
  }
}

// Greetings go to chat - UNLESS message also contains order intent
const greetings = ['hi', 'hello', 'hey', 'good morning','morning', 'good afternoon', 'good evening', 'halo', 'hai', 'pagi', 'siang', 'malam', 'test', 'help'];
const greetingOrderTerms = ['pesan', 'order', 'catering', 'mau pesan', 'mau order', 'ingin pesan', 'ingin order', 'saya mau', 'book', 'beli'];
const isGreetingMsg = greetings.some(g => msg === g || msg.startsWith(g + ' ') || msg.startsWith(g + ','));
if (isGreetingMsg && !greetingOrderTerms.some(t => msg.includes(t))) {
  return { flow: 'chat', context: context };
}

// Order intent keywords
const orderKeywords = ['order', 'pesan', 'catering', 'book', 'food', 'makan', 'package', 'paket', 'would like', 'beli', 'confirm', 'confrim',
  'mau pesan', 'saya mau pesan', 'pesan dong', 'ingin pesan',
  'mau order', 'saya mau order', 'boleh pesan', 'boleh order',
  'pesan sekarang', 'order sekarang', 'pesan catering', 'mau catering'];
if (orderKeywords.some(k => msg.includes(k))) {
  return { flow: 'order', context: context };
}

// ?? Edit intent keywords
const editKeywords = ['change', 'ganti', 'ubah', 'update', 'modify', 'remove', 'add', 'tambah', 'kurang', 'instead'];
if (editKeywords.some(k => msg.includes(k)) && isInOrderMode) {
  return { flow: 'order', context: { ...context, _isEditIntent: true } };
}

// Check if message contains date patterns (catches "10th may", "may 10th", etc.)
const hasDate = /\d{1,2}(?:st|nd|rd|th)?\s+(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)/i.test(msg) ||
                /(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s+\d{1,2}(?:st|nd|rd|th)?/i.test(msg);

// Check if message looks like order details
const hasOrderComma = msg.includes(',') && (/d/.test(msg) || hasDate);
const looksLikeOrderDetails = hasOrderComma || hasDate || 
  /\d+\s+(?:guest|people|orang)/i.test(msg) ||
  /package\s+[a-c]/i.test(msg);

if (looksLikeOrderDetails) {
  return { flow: 'order', context: context };
}

// ?? Check for date-only queries (like "11th", "11th may", "what about 11th")
const hasDateOnly = /\b\d{1,2}(?:st|nd|rd|th)?\b/.test(msg);
const isStandaloneDate = hasDateOnly && msg.split(' ').length <= 4;

if (isStandaloneDate) {
  return { flow: 'order', context: context };
}

return { flow: 'chat', context: context };

// ========================================
// AI CHAT PROMPT - WITH BETTER CONTEXT HANDLING & BILINGUAL SUPPORT
// ========================================

const context = $input.item.json.context;
const lang = context.lang || $input.item.json.lang || 'id';
const isEnglish = lang === 'en';
const profile = context.customerProfile || {};
// lang already declared above
const history = context.conversationHistory || [];
const msg = (context.message || '').toLowerCase().trim();
const isAfterHolidayRejection = context._isAfterHolidayRejection || false;

// Handle after-holiday-rejection acknowledgment
if (isAfterHolidayRejection) {
  // If customer mentions a specific date, confirm it's available
  const hasDate = /\d{1,2}(?:st|nd|rd|th)?/i.test(context.message);
  if (hasDate) {
    const dateMatch = context.message.match(/\d{1,2}(?:st|nd|rd|th)?\s*(?:of\s*)?(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)/i);
    const mentionedDate = dateMatch ? dateMatch[0] : 'that date';

    if (lang === 'en') {
      return { 
        model: "qwen3:8b", 
        stream: false,
        think: false, 
        temperature: 0.1, 
        max_tokens: 25, 
        prompt: `Say exactly: "Yes, we're open for ${mentionedDate}!" Do NOT change the date format, do NOT convert to day name, do NOT add anything else. Output ONLY that sentence. No quotes.` 
      };
    } else {
      return { 
        model: "qwen3:8b", 
        stream: false,
        think: false, 
        temperature: 0.1, 
        max_tokens: 25, 
        prompt: `Say exactly: "Ya, kami buka untuk tanggal ${mentionedDate}!" Do NOT change the date format, do NOT convert to day name, do NOT add anything else. Output ONLY that sentence. No quotes.` 
      };
    }
  }

  if (lang === 'en') {
    return { 
      model: "qwen3:8b", 
      stream: false,
        think: false, 
      temperature: 0.7, 
      max_tokens: 20, 
      prompt: `Output ONLY a very short phrase like "No problem! Which date works for you?" without quotes or explanation.` 
    };
  } else {
    return { 
      model: "qwen3:8b", 
      stream: false,
        think: false, 
      temperature: 0.7, 
      max_tokens: 25, 
      prompt: `Output ONLY a very short phrase like "Tidak masalah! Tanggal berapa yang cocok untuk Anda?" without quotes or explanation.` 
    };
  }
}

// Handle cancellation/acknowledgment messages
const cancelMessages = ['cancel', 'batal', 'sorry', 'okay sorry', 'nevermind', 'no thanks'];
if (cancelMessages.some(c => msg.includes(c))) {
  if (lang === 'en') {
    return { 
      model: "qwen3:8b", 
      stream: false,
        think: false, 
      temperature: 0.7, 
      max_tokens: 30, 
      prompt: `Customer said: "${context.message}". They are canceling or acknowledging something. Respond with ONE very short friendly sentence in English WITHOUT quotation marks. Say something like: No problem! or Feel free to order anytime! Do NOT mention dates, orders, or menus. Just output plain text.` 
    };
  } else {
    return { 
      model: "qwen3:8b", 
      stream: false,
        think: false, 
      temperature: 0.7, 
      max_tokens: 35, 
      prompt: `Customer said: "${context.message}". They are canceling or acknowledging something. Respond with ONE very short friendly sentence in Bahasa Indonesia WITHOUT quotation marks. Say something like: Tidak masalah! or Silakan memesan kapan saja! Do NOT mention dates, orders, or menus. Just output plain text.` 
    };
  }
}

// Filter out order-related messages so AI doesn't reference them
const recentMessages = history.slice(-10)
  .filter(msg => !msg.content.includes('Please provide') && 
                 !msg.content.includes('Still need') && 
                 !msg.content.includes('ORDER SUMMARY') && 
                 !msg.content.includes('ORDER CONFIRMED') &&
                 !msg.content.includes("we're closed on") &&
                 !msg.content.includes("Let me check") &&
                 !msg.content.includes("choose another date") &&
                 !msg.content.includes("Our Menu ???") &&
                 !msg.content.includes("Yes, we're open"))
  .map(msg => `${msg.role === 'user' ? 'Customer' : 'Assistant'}: ${msg.content}`)
  .join('\n');

// Simple responses for common messages
if (msg === 'thanks' || msg === 'thank you' || msg === 'thx' || msg === 'makasih' || msg === 'terima kasih') {
  if (lang === 'en') {
    return { model: "qwen3:8b", stream: false,
        think: false, temperature: 0.7, max_tokens: 30, prompt: `Reply to "thank you" with ONE very short friendly sentence in English. Say you're happy to help and they can order anytime. Do NOT use quotation marks.` };
  } else {
    return { model: "qwen3:8b", stream: false,
        think: false, temperature: 0.7, max_tokens: 30, prompt: `Reply to a thank you message with ONE very short friendly sentence in Bahasa Indonesia. Say you're happy to help and they can order anytime (e.g. "Sama-sama! Senang bisa membantu."). Do NOT use quotation marks.` };
  }
}

// Check if we've already introduced ourselves
const hasIntroduced = history.some(h => 
  h.role === 'assistant' && 
  (h.content.includes("Leeds Assistant") || 
   h.content.includes("ready to help") ||
   h.content.includes("siap membantu"))
);

// Check if last few messages are just greetings back and forth
const greetingWords = ['hi', 'hello', 'hey', 'halo', 'hai', 'good morning', 'good afternoon', 'good evening', 'pagi', 'siang', 'malam', 'morning', 'afternoon', 'evening'];
const lastFewMessages = history.slice(-4);
const allJustGreetings = lastFewMessages.length >= 2 && lastFewMessages.every(h => {
  const content = (h.content || '').toLowerCase().trim();
  return greetingWords.some(g => content.startsWith(g)) || content.length < 10;
});

const isFirstInteraction = !hasIntroduced && !allJustGreetings;
const isGreeting = greetingWords.some(g => msg === g || msg.startsWith(g + ' ') || msg.startsWith(g + ','));

const prompt = `You are Leeds Assistant, a friendly AI for Leeds Catering. Keep responses very short.\\n\\nCRITICAL LANGUAGE RULE: You MUST reply in ${isEnglish ? 'English ONLY' : 'Bahasa Indonesia ONLY'}. Never switch languages. If unsure, match the customer's language.

Current customer: ${profile.name || 'Guest'}
${isFirstInteraction ? 'This is your FIRST interaction with this customer.' : 'You have already greeted this customer.'}
${allJustGreetings ? 'Customer is just saying greetings repeatedly. Nudge them to order.' : ''}

Previous conversation:
${recentMessages || 'This is the start of the conversation'}

Customer's message: "${context.message}"

RULES:
1. Respond with 1 very short sentence only
2. Be warm and friendly
3. ${lang === 'en' 
    ? (isFirstInteraction && isGreeting ? 'INTRODUCE yourself as Leeds Assistant briefly, then ask how you can help. Example: "Hi! I\'m Leeds Assistant, ready to help with your catering order!"' : allJustGreetings ? 'Customer keeps greeting. Nudge them to order. Example: "Ready to order? Just let me know what you need!"' : 'Do NOT introduce yourself. Keep it brief. Example: "Hi! How can I help?"')
    : (isFirstInteraction && isGreeting ? 'INTRODUCE yourself as Leeds Assistant briefly in Indonesian, then ask how you can help. Example: "Halo! Saya Leeds Assistant, siap membantu pesanan catering Anda!"' : allJustGreetings ? 'Customer keeps greeting. Nudge them to order in Indonesian. Example: "Siap memesan? Beri tahu saja apa yang Anda butuhkan!"' : 'Do NOT introduce yourself. Keep it brief in Indonesian. Example: "Halo! Ada yang bisa saya bantu?"')
   }
4. Never mention dates, menus, or order forms in greetings
5. If customer asks if you are open or about availability, say YES we are open and end with a short question inviting them to order, e.g. "Yes, we're open! Would you like to place an order?" or in Indonesian "Ya, kami buka! Ingin memesan sekarang?"
5. Be direct and helpful
6. ${lang === 'en' ? 'RESPOND IN ENGLISH.' : 'RESPOND IN BAHASA INDONESIA.'}

Respond naturally:`;

const fallbackMsg = lang === 'en'
  ? "Hi there! I'm currently running with limited features ?? You can still place orders by saying \"order please\" we'll send you the form, thanks! ??"
  : "Halo! Saat ini sistem kami sedang dalam pemeliharaan/fitur terbatas ?? Namun Anda tetap bisa melakukan pemesanan dengan mengetik \"pesan\" dan kami akan mengirimkan formulirnya, terima kasih! ??";

return { 
  model: "qwen3:8b", 
  stream: false,
        think: false, 
  temperature: 0.7, 
  max_tokens: 50, 
  prompt: prompt
};

// ========================================
