function getLastOrderSummary() {
  const result = {
    name: null, phoneNumber: null, eventDate: null, displayDate: null, deliveryTime: null, eventType: null,
    menuItems: [], quantity: null, address: null, specialRequests: null
  };

  // First pass: authoritative ORDER SUMMARY - only when last bot msg IS an ORDER SUMMARY
  // If last bot msg is conversational, skip to second pass to avoid cross-session bleed
  const _lastAsstMsg = [...history].reverse().find(h => h.role === 'assistant' && h.content);
  const _lastMsgIsOrderSummary = _lastAsstMsg && (
    _lastAsstMsg.content.includes('ORDER SUMMARY') || _lastAsstMsg.content.includes('RINGKASAN PESANAN')
  );
  if (_lastMsgIsOrderSummary)
  for (let i = history.length - 1; i >= 0; i--) {
    const h = history[i];
    if (h.role !== 'assistant' || !h.content) continue;
    if (!(h.content.includes('ORDER SUMMARY') || h.content.includes('RINGKASAN PESANAN'))) continue;

    const nameMatch  = h.content.match(/Name:\s*(.+?)(?:\n|$)/i);
    const phoneMatch = h.content.match(/Phone:\s*(.+?)(?:\n|$)/i);
    const dateMatch  = h.content.match(/(?:Delivery Date|Event Date):\s*(.+?)(?:\n|$)/i);
    const timeMatch  = h.content.match(/Delivery Time:\s*(.+?)(?:\n|$)/i);
    const typeMatch  = h.content.match(/Event:\s*(.+?)(?:\n|$)/i);
    const qtyMatch   = h.content.match(/Quantity:\s*(\d+)/i);
    const addrMatch  = h.content.match(/Delivery Address:\s*(.+?)(?:\n|$)/i) || h.content.match(/Address:\s*(.+?)(?:\n|$)/i);
    const specMatch  = h.content.match(/Special Request:\s*(.+?)(?:\n|$)/i);

    if (nameMatch)  result.name         = nameMatch[1].trim();
    if (phoneMatch) result.phoneNumber  = phoneMatch[1].trim();
    if (dateMatch)  result.eventDate    = dateMatch[1].trim();
    if (timeMatch)  result.deliveryTime = timeMatch[1].trim();
    if (typeMatch)  result.eventType    = typeMatch[1].trim();
    if (qtyMatch)   result.quantity     = qtyMatch[1].trim();
    if (addrMatch)  result.address      = addrMatch[1].trim();
    if (specMatch && specMatch[1].trim() !== '!' && specMatch[1].trim() !== 'None') {
      result.specialRequests = specMatch[1].trim();
    }

    const menuSection = h.content.match(/Menu:\n([\s\S]*?)(?:\nAddress|$)/);
    if (menuSection) {
      menuSection[1].split('\n').forEach(line => {
        const m = line.match(/(.+?)\s+x(\d+)/i);
        const priceM = line.match(/\(Rp ([\d.,]+)\/person\)/i);
        if (m) {
          const menuName = m[1].trim().replace(/^[?\s]+/, '').trim();
          const pricePerPerson = priceM ? parseInt(priceM[1].replace(/[.,]/g, '').replace(/\.(\d{3})$/, '$1')) : 0;
          result.menuItems.push({ menu: menuName, quantity: parseInt(m[2]), pricePerPerson });
        }
      });
    }
    if (result.menuItems.length === 0 && h.menuItems && Array.isArray(h.menuItems)) {
      result.menuItems = h.menuItems;
    }
    if (result.eventDate) {
      const dateFix = normalizeDateWithYearFix(result.eventDate);
      if (dateFix.normalized) { result.eventDate = dateFix.normalized; result.displayDate = dateFix.displayDate; }
    }
    console.log('getLastOrderSummary (ORDER SUMMARY):', JSON.stringify(result));
    return result;
  }

  // Second pass: parse conversational "Here's what I have" messages to recover partial data
  for (let i = history.length - 1; i >= 0; i--) {
    const h = history[i];
    if (h.role !== 'assistant' || !h.content) continue;
    const isConvMsg = h.content.includes("Here's what I have") || h.content.includes('Berikut data yang saya catat');
    if (!isConvMsg) continue;

    h.content.split('\n').forEach(line => {
      const nameM = line.match(/(?:Nama|Name):\s*(.+)$/i);
      if (nameM && !/\d/.test(nameM[1])) result.name = nameM[1].trim();

      const dateM = line.match(/(?:Tanggal Pengiriman|Delivery Date|Tanggal|Date):\s*(.+)$/i);
      if (dateM) result.eventDate = dateM[1].trim();

      const menuM = line.match(/Menu:\s*(.+)$/i);
      if (menuM) {
        menuM[1].split(',').forEach(part => {
          const m = part.trim().match(/^(.+?)\s+x(\d+)$/i);
          if (m) result.menuItems.push({ menu: m[1].trim(), quantity: parseInt(m[2]) });
        });
      }

      const addrM = line.match(/(?:Alamat Pengiriman|Delivery Address|Alamat|Address):\s*(.+)$/i);
      if (addrM) result.address = addrM[1].trim();

      const phoneM = line.match(/(?:Telepon|Phone):\s*(.+)$/i);
      if (phoneM) result.phoneNumber = phoneM[1].trim();

      const timeM = line.match(/(?:Waktu Pengiriman|Delivery Time):\s*(.+)$/i);
      if (timeM) result.deliveryTime = timeM[1].trim();

      const qtyM = line.match(/(?:Jumlah|Quantity):\s*(\d+)/i);
      if (qtyM) result.quantity = qtyM[1].trim();

      const evtM = line.match(/(?:Acara|Event):\s*(.+)$/i);
      if (evtM) result.eventType = evtM[1].trim();
    });

    if (result.eventDate) {
      const dateFix = normalizeDateWithYearFix(result.eventDate);
      if (dateFix.normalized) { result.eventDate = dateFix.normalized; result.displayDate = dateFix.displayDate; }
    }
    if (result.eventDate || result.address || result.menuItems.length > 0) {
      console.log('getLastOrderSummary (conversational):', JSON.stringify(result));
      return result;
    }
  }

  return result;
}
