// Function to extract current order from history
function getCurrentOrderFromHistory() {
  let currentMenuItems = [];
  let currentEventDate = '';
  let currentEventType = '';
  let currentAddress = '';
  let currentSpecialRequest = '';

  for (let i = history.length - 1; i >= 0; i--) {
    const h = history[i];
    if (h.role === 'assistant' && h.content && (h.content.includes('ORDER SUMMARY') || h.content.includes('RINGKASAN PESANAN'))) {
      // Extract current menu items
      const menuSectionMatch = h.content.match(/Menu:\n([\s\S]*?)(?:\nAddress|$)/);
      if (menuSectionMatch) {
        const menuSection = menuSectionMatch[1];
        const itemLines = menuSection.split('\n');
        for (const line of itemLines) {
          const itemMatch = line.match(/(.+?)\s+x(\d+)/i);
          if (itemMatch) {
            currentMenuItems.push({
              menu: itemMatch[1].trim(),
              quantity: parseInt(itemMatch[2])
            });
          }
        }
      }

      // Extract other details
      const dateMatch = h.content.match(/Event Date:\s*(.+?)(?:\n|$)/i);
      if (dateMatch) currentEventDate = dateMatch[1].trim();

      const typeMatch = h.content.match(/Event:\s*(.+?)(?:\n|$)/i);
      if (typeMatch) currentEventType = typeMatch[1].trim();

      const addrMatch = h.content.match(/Address:\s*(.+?)(?:\n|$)/i);
      if (addrMatch) currentAddress = addrMatch[1].trim();

      const specialMatch = h.content.match(/Special Request:\s*(.+?)(?:\n|$)/i);
      if (specialMatch && specialMatch[1].trim() !== '!' && specialMatch[1].trim() !== 'None') {
        currentSpecialRequest = specialMatch[1].trim();
      }

      break;
    }
  }

  return { currentMenuItems, currentEventDate, currentEventType, currentAddress, currentSpecialRequest };
}

