const changePatterns = [
  /change\s+(?:the\s+)?(month|date|day)\s+(?:to\s+)?(.+)/i,
  /change\s+(?:to\s+)?(.+)/i,
  /make\s+(?:it|the)\s+(.+)/i,
  /update\s+(?:the\s+)?(month|date|day)\s+(?:to\s+)?(.+)/i
];

let changeMatch = null;
for (const pattern of changePatterns) {
  changeMatch = userMessage.match(pattern);
  if (changeMatch) break;
}

// Only process date change if it's NOT already handled by new date query or menu edit
if (changeMatch && !extractedData.menuItems && !extractedData._isNewOrderAttempt) {
  console.log('Date change request detected:', changeMatch[0]);

  let existingDate = '';
  for (let i = history.length - 1; i >= 0; i--) {
    const h = history[i];
    if (h.role === 'assistant' && h.content) {
      const dateMatch = h.content.match(/Event Date:\s*([^\n]+)/i);
      if (dateMatch) {
        existingDate = dateMatch[1].trim();
        break;
      }
    }
  }

  if (existingDate) {
    console.log('Existing date found:', existingDate);

    const monthNames = ['january', 'february', 'march', 'april', 'may', 'june', 
                        'july', 'august', 'september', 'october', 'november', 'december'];

    let existingDay = '';
    let existingMonth = '';
    let existingYear = '';

    let dateParts = existingDate.match(/(\d{1,2})\s+([a-z]+)\s*(\d{4})?/i);
    if (dateParts) {
      existingDay = dateParts[1];
      existingMonth = dateParts[2].toLowerCase();
      existingYear = dateParts[3] || new Date().getFullYear().toString();
    }

    let newValue = changeMatch[2] || changeMatch[1] || '';
    newValue = newValue.trim();

    if (changeMatch[1] && changeMatch[2] && ['month', 'date', 'day'].includes(changeMatch[1].toLowerCase())) {
      newValue = changeMatch[2].trim();
    }

    if (!changeMatch[1] || (changeMatch[1] && !['month', 'date', 'day'].includes(changeMatch[1].toLowerCase()))) {
      newValue = (changeMatch[2] || changeMatch[1] || '').trim();
    }

    console.log('New value requested:', newValue);

    const monthMatch = monthNames.find(m => 
      m === newValue.toLowerCase() || 
      m.startsWith(newValue.toLowerCase()) || 
      newValue.toLowerCase().startsWith(m.substring(0, 3))
    );

    if (monthMatch) {
      existingMonth = monthMatch;
      console.log('Changing month to:', existingMonth);
    } else if (/^\d{1,2}$/.test(newValue)) {
      existingDay = newValue.padStart(2, '0');
      console.log('Changing day to:', existingDay);
    } else if (/^\d{4}$/.test(newValue)) {
      existingYear = newValue;
      console.log('Changing year to:', existingYear);
    }

    if (existingDay && existingMonth) {
      extractedData.eventDate = `${existingDay} ${existingMonth} ${existingYear}`;
      console.log('Rebuilt date:', extractedData.eventDate);

      // Preserve current menu items when only changing date
      const currentOrder = getCurrentOrderFromHistory();
      if (currentOrder.currentMenuItems.length > 0 && !extractedData.menuItems) {
        extractedData.menuItems = currentOrder.currentMenuItems;
        const totalQty = currentOrder.currentMenuItems.reduce((sum, item) => sum + item.quantity, 0);
        extractedData.quantity = String(totalQty);
        extractedData.menu = currentOrder.currentMenuItems.map(i => `${i.menu} x${i.quantity}`).join(', ');
        if (currentOrder.currentEventType) extractedData.eventType = currentOrder.currentEventType;
        if (currentOrder.currentAddress) extractedData.address = currentOrder.currentAddress;
      }
    }
  }
}

// ?? FIX BARE DATE NUMBERS
if (extractedData.eventDate && !extractedData.menuItems) {
  const bareDate = extractedData.eventDate.trim().replace(/(\d+)(st|nd|rd|th)$/i, '$1');

  if (/^\d{1,2}$/.test(bareDate)) {
    const monthNames = ['january', 'february', 'march', 'april', 'may', 'june', 
                        'july', 'august', 'september', 'october', 'november', 'december'];
    const currentMonth = monthNames[new Date().getMonth()];
    const currentYear = new Date().getFullYear();
    extractedData.eventDate = `${bareDate} ${currentMonth} ${currentYear}`;
    console.log('Added current month and year to bare date:', extractedData.eventDate);
  }
}

// ?? If eventDate is just a month name
if (extractedData.eventDate && !extractedData.menuItems && !extractedData._skipHistoryMerge) {
  const monthNames = ['january', 'february', 'march', 'april', 'may', 'june', 
                      'july', 'august', 'september', 'october', 'november', 'december'];
  const isJustMonth = monthNames.some(m => extractedData.eventDate.toLowerCase().trim() === m);

  if (isJustMonth) {
    for (let i = history.length - 1; i >= 0; i--) {
      const h = history[i];
      if (h.role === 'assistant' && h.content) {
