          break;
        }
      }
    }
  }
}

// ?? CLEAR non-date words from eventDate
const nonDateWords = ['confirm', 'confrim', 'confirmed', 'yes', 'ok', 'okay', 'no', 'cancel'];
if (extractedData.eventDate && nonDateWords.includes(extractedData.eventDate.toLowerCase().trim())) {
  console.log('Clearing non-date word from eventDate:', extractedData.eventDate);
  extractedData.eventDate = '';
}

// ?? STRIP ordinal suffixes from eventDate
if (extractedData.eventDate) {
  extractedData.eventDate = extractedData.eventDate.replace(/(\d+)(st|nd|rd|th)\b/gi, '$1');
}

// ?? CLEAN SPECIAL REQUEST
if (extractedData.specialRequest) {
  const removePatterns = [
    /for multiple menus:.*$/gi,
    /package a x\d+.*$/gi,
    /package b x\d+.*$/gi,
    /you can just tell me naturally/gi,
    /please provide your order details/gi,
    /for example:.*$/gi
  ];

  for (const pattern of removePatterns) {
    extractedData.specialRequest = extractedData.specialRequest.replace(pattern, '').trim();
  }

  extractedData.specialRequest = extractedData.specialRequest.replace(/^[!.,;:]+$/, '').trim();

  if (!extractedData.specialRequest || extractedData.specialRequest.length === 0) {
    delete extractedData.specialRequest;
  }
}

// Fix menu matching for single letters
if (extractedData.menu && !extractedData.menuItems) {
  const menuVal = extractedData.menu.toLowerCase().trim();

  const choiceMatch = menuVal.match(/choice\s*[=:]\s*(\w+)/i);
  const cleanVal = choiceMatch ? choiceMatch[1] : menuVal;

  if (cleanVal.length === 1) {
    for (const m of menus) {
      if (m.name.toUpperCase().endsWith(cleanVal.toUpperCase())) {
        extractedData.menu = m.name;
        break;
      }
    }
  }

  if (!menus.some(m => m.name === extractedData.menu)) {
    const pkgMatch = cleanVal.match(/package\s+([a-c])/i) || cleanVal.match(/paket\s+([a-c])/i);
    if (pkgMatch) {
      for (const m of menus) {
        if (m.name.toUpperCase().endsWith(pkgMatch[1].toUpperCase())) {
          extractedData.menu = m.name;
          break;
