// Normalize date to YYYY-MM-DD (handles ordinals like "10th")
function normalizeDate(dateStr) {
  if (!dateStr) return '';
  let cleaned = dateStr.trim().toLowerCase();

  if (/^\d{4}-\d{2}-\d{2}$/.test(cleaned)) return cleaned;

  // REMOVE ordinal suffixes: 1st, 2nd, 3rd, 4th, 10th, etc.
  cleaned = cleaned.replace(/(\d+)(st|nd|rd|th)\b/g, '$1');

  const months = {
    'january': '01', 'jan': '01', 'february': '02', 'feb': '02',
    'march': '03', 'mar': '03', 'april': '04', 'apr': '04',
    'may': '05', 'mei': '05', 'june': '06', 'jun': '06',
    'july': '07', 'jul': '07', 'august': '08', 'aug': '08',
    'september': '09', 'sep': '09', 'october': '10', 'oct': '10',
    'november': '11', 'nov': '11', 'december': '12', 'dec': '12'
  };

  // "10 may" or "10th may"
  let match = cleaned.match(/(\d{1,2})\s+([a-z]+)/);
  if (match) {
    const day = match[1].padStart(2, '0');
    const monthName = match[2];
    for (const [name, num] of Object.entries(months)) {
      if (monthName === name || monthName.startsWith(name)) {
        return `2026-${num}-${day}`;
      }
    }
  }

  // NEW: "may 10" or "may 10th" (month first)
  match = cleaned.match(/([a-z]+)\s+(\d{1,2})/);
  if (match) {
    const monthName = match[1];
    const day = match[2].padStart(2, '0');
    for (const [name, num] of Object.entries(months)) {
      if (monthName === name || monthName.startsWith(name)) {
        return `2026-${num}-${day}`;
      }
    }
  }

  return '';
}

